// Generated by scripts/embed-migrations.ts from supabase/migrations. Do not edit.
export const MIGRATIONS: { name: string; sql: string }[] = [
  { name: "0001_ideation_schema.sql", sql: "-- Content Ideation Engine: core schema.\n-- Lives in its own `ideation` schema inside the studio's Supabase Postgres so it\n-- never collides with studio tables and can be dropped cleanly.\n\n-- Supabase keeps extensions in their own schema; this also works on plain Postgres.\ncreate schema if not exists extensions;\ncreate extension if not exists vector with schema extensions;\n\ncreate schema if not exists ideation;\nset search_path = ideation, public, extensions;\n\n-- ---------------------------------------------------------------------------\n-- Workspaces and the Brand Brain\n-- ---------------------------------------------------------------------------\n\ncreate table workspaces (\n  id                   text primary key,                -- wsp_...\n  studio_workspace_id  text not null unique,\n  name                 text not null,\n  created_at           timestamptz not null default now()\n);\n\ncreate table brand_brains (\n  workspace_id   text primary key references workspaces(id) on delete cascade,\n  website_url    text,\n  brand_kit      jsonb not null default '{}'::jsonb,     -- colors, fonts, logo refs\n  goal           text not null check (goal in ('reach', 'engagement', 'leads', 'sales')),\n  language       text not null,                          -- BCP 47, e.g. en-NG\n  timezone       text not null default 'UTC',            -- IANA; posting-time features use it\n  trends_geo     text,                                   -- ISO country for Trends RSS / YouTube charts, e.g. NG\n  tone_words     text[] not null default '{}',\n  pillars        text[] not null default '{}',\n  audience       text,\n  offers         jsonb not null default '[]'::jsonb,     -- [{name, url, price?}]\n  banned_topics  text[] not null default '{}',\n  draft          jsonb,                                  -- Claude's draft before confirmation\n  confirmed_at   timestamptz,\n  updated_at     timestamptz not null default now()\n);\n\n-- Accounts the studio already connected. OAuth tokens stay in the studio; we\n-- only keep the reference the studio's token resolver understands.\ncreate table connected_accounts (\n  id                     text primary key,               -- acc_...\n  workspace_id           text not null references workspaces(id) on delete cascade,\n  platform               text not null check (platform in ('tiktok', 'instagram', 'facebook', 'youtube', 'linkedin')),\n  external_account_id    text not null,\n  handle                 text,\n  account_kind           text not null default 'personal' check (account_kind in ('personal', 'business', 'creator', 'page', 'organization', 'channel')),\n  studio_connection_id   text not null,\n  connected_at           timestamptz not null default now(),\n  disconnected_at        timestamptz,\n  unique (platform, external_account_id, workspace_id)\n);\n\ncreate table competitors (\n  id            text primary key,                        -- cmp_...\n  workspace_id  text not null references workspaces(id) on delete cascade,\n  name          text not null,\n  -- {instagram: \"handle\", youtube: \"UC...\", tiktok: \"handle\", linkedin: \"...\", facebook: \"...\"}\n  handles       jsonb not null default '{}'::jsonb,\n  created_at    timestamptz not null default now()\n);\n\n-- The spec caps competitors at 5 per workspace.\ncreate function enforce_competitor_limit() returns trigger language plpgsql as $$\nbegin\n  if (select count(*) from ideation.competitors where workspace_id = new.workspace_id) >= 5 then\n    raise exception 'a workspace can track at most 5 competitors';\n  end if;\n  return new;\nend $$;\n\ncreate trigger competitors_limit before insert on competitors\n  for each row execute function enforce_competitor_limit();\n\n-- ---------------------------------------------------------------------------\n-- Evidence: competitor posts, signals and audience comments\n-- ---------------------------------------------------------------------------\n\ncreate table competitor_posts (\n  id               text primary key,                     -- cpp_...\n  workspace_id     text not null references workspaces(id) on delete cascade,\n  competitor_id    text not null references competitors(id) on delete cascade,\n  platform         text not null,\n  platform_post_id text not null,\n  permalink        text,\n  title            text,\n  caption          text,\n  thumbnail_url    text,\n  media_type       text,\n  published_at     timestamptz,\n  views            bigint,\n  likes            bigint,\n  comments         bigint,\n  outlier_ratio    numeric,                              -- vs. the account's last-30 median\n  is_winner        boolean generated always as (outlier_ratio >= 2.5) stored,\n  vision_tags      jsonb,                                -- hook/visual tags from Claude vision\n  embedding        vector(384),\n  source_url       text not null,                        -- legal: always keep source + fetch date\n  fetched_at       timestamptz not null default now(),\n  unique (competitor_id, platform, platform_post_id)\n);\ncreate index competitor_posts_winners on competitor_posts (workspace_id, platform) where outlier_ratio >= 2.5;\n\ncreate table signals (\n  id            text primary key,                        -- sig_...\n  workspace_id  text references workspaces(id) on delete cascade,  -- null = global (e.g. Trends RSS)\n  source        text not null check (source in (\n                  'google_trends_rss', 'wikipedia_pageviews', 'youtube_most_popular',\n                  'own_comments', 'competitor_comments', 'stackexchange', 'hackernews',\n                  'tiktok_oembed', 'claude_web_search')),\n  topic         text not null,\n  title         text,\n  url           text,\n  geo           text,\n  momentum      numeric,                                 -- 0..1, rising = high\n  payload       jsonb not null default '{}'::jsonb,\n  embedding     vector(384),\n  observed_at   timestamptz not null default now(),\n  observed_day  date not null default (now() at time zone 'utc')::date,\n  fetched_at    timestamptz not null default now()\n);\ncreate index signals_ws_source on signals (workspace_id, source, observed_at desc);\ncreate unique index signals_dedupe on signals (coalesce(workspace_id, ''), source, topic, coalesce(geo, ''), observed_day);\n\ncreate table audience_comments (\n  id                text primary key,                    -- cmt_...\n  workspace_id      text not null references workspaces(id) on delete cascade,\n  origin            text not null check (origin in ('own', 'competitor')),\n  platform          text not null,\n  platform_post_id  text not null,\n  platform_comment_id text not null,\n  text              text not null,\n  like_count        integer,\n  is_question       boolean not null default false,\n  published_at      timestamptz,\n  fetched_at        timestamptz not null default now(),\n  unique (platform, platform_comment_id)\n);\ncreate index audience_comments_questions on audience_comments (workspace_id, published_at desc) where is_question;\n\n-- ---------------------------------------------------------------------------\n-- Ideas and briefs (stages 1 and 2)\n-- ---------------------------------------------------------------------------\n\ncreate table ideas (\n  id               text primary key,                     -- ide_...\n  workspace_id     text not null references workspaces(id) on delete cascade,\n  run_id           text,                                 -- precompute run that produced it\n  mode             text not null check (mode in ('autopilot', 'give_me_ideas', 'refine')),\n  platform         text,                                 -- target platform the card was scored for; null = general\n  title            text not null,\n  why_now          text not null,\n  core_idea        text not null,\n  evidence         jsonb not null default '[]'::jsonb,   -- [{kind, id, url, summary}] own winners first\n  -- learnable features: hook_type, format, pillar, length_bucket, idea_source, cta_type, visual_style, language\n  features         jsonb not null default '{}'::jsonb,\n  score            numeric,                              -- 0..100 opportunity score\n  score_components jsonb,                                -- {L,F,P,M,W,G}\n  relative_label   text,                                 -- top_third | middle_third | bottom_third\n  confidence       text check (confidence in ('low', 'medium', 'high')),\n  content_type     text,\n  effort           text check (effort in ('low', 'medium', 'high')),\n  risks            text[] not null default '{}',\n  slot             text not null default 'explore' check (slot in ('exploit', 'explore')),\n  label            text generated always as (case when slot = 'exploit' then 'proven' else 'test' end) stored,\n  status           text not null default 'candidate' check (status in ('candidate', 'shortlisted', 'selected', 'briefed', 'dismissed')),\n  embedding        vector(384),\n  created_at       timestamptz not null default now(),\n  expires_at       timestamptz\n);\ncreate index ideas_shortlist on ideas (workspace_id, status, score desc);\n\n-- The studio reads this table as a queue (status = 'queued'). Idempotent on id (= brief_id).\n-- 'draft' briefs are pre-generated overnight for Autopilot and are invisible to the studio.\ncreate table briefs (\n  id            text primary key,                        -- brf_...\n  idea_id       text not null references ideas(id) on delete cascade,\n  workspace_id  text not null references workspaces(id) on delete cascade,\n  kind          text not null check (kind in ('platform', 'general')),\n  platform      text,\n  payload       jsonb not null,                          -- brief.v1\n  status        text not null default 'queued' check (status in ('draft', 'queued', 'delivered', 'acknowledged', 'failed')),\n  attempts      integer not null default 0,\n  last_error    text,\n  created_at    timestamptz not null default now(),\n  delivered_at  timestamptz,\n  check ((kind = 'platform') = (platform is not null))\n);\ncreate index briefs_queue on briefs (status, created_at) where status in ('queued', 'failed');\n\n-- ---------------------------------------------------------------------------\n-- Stage 3 (reserved) output contract, and analytics (stage 4)\n-- ---------------------------------------------------------------------------\n\n-- `published_post` from the reserved scheduling block. Analytics depends only on this.\ncreate table published_posts (\n  id                 text primary key,                   -- pst_...\n  workspace_id       text not null references workspaces(id) on delete cascade,\n  connected_account_id text references connected_accounts(id) on delete set null,\n  platform           text not null,\n  platform_post_id   text not null,\n  asset_id           text,\n  brief_id           text references briefs(id) on delete set null,\n  idea_id            text references ideas(id) on delete set null,\n  published_at       timestamptz not null,\n  permalink          text,\n  caption            text,\n  duration_seconds   numeric,\n  -- features frozen at publish time so learning is not affected by later edits to the idea\n  features           jsonb not null default '{}'::jsonb,\n  link_status        text not null default 'linked' check (link_status in ('linked', 'suggested', 'confirmed', 'unmatched')),\n  match_confidence   numeric,\n  created_at         timestamptz not null default now(),\n  unique (platform, platform_post_id)\n);\ncreate index published_posts_ws_platform on published_posts (workspace_id, platform, published_at desc);\n\ncreate table snapshot_jobs (\n  published_post_id text not null references published_posts(id) on delete cascade,\n  offset_label      text not null check (offset_label in ('1h', '6h', '24h', '72h', '7d', '28d', 'backfill')),\n  due_at            timestamptz not null,\n  status            text not null default 'pending' check (status in ('pending', 'done', 'failed')),\n  attempts          integer not null default 0,\n  not_before        timestamptz,                         -- deferred by rate limits, never dropped\n  last_error        text,\n  primary key (published_post_id, offset_label)\n);\ncreate index snapshot_jobs_due on snapshot_jobs (due_at) where status = 'pending';\n\n-- Normalised metric model: nulls mean the platform does not provide the field. Never guessed.\ncreate table metric_snapshots (\n  published_post_id text not null references published_posts(id) on delete cascade,\n  offset_label      text not null check (offset_label in ('1h', '6h', '24h', '72h', '7d', '28d', 'backfill')),\n  captured_at       timestamptz not null default now(),\n  views             bigint,\n  reach             bigint,\n  likes             bigint,\n  comments          bigint,\n  shares            bigint,\n  saves             bigint,\n  sends             bigint,\n  avg_watch_seconds numeric,\n  completion_rate   numeric,\n  link_clicks       bigint,\n  profile_visits    bigint,\n  followers_gained  bigint,\n  raw               jsonb,\n  primary key (published_post_id, offset_label)\n);\n\ncreate table account_metrics_daily (\n  connected_account_id text not null references connected_accounts(id) on delete cascade,\n  day                  date not null,\n  followers            bigint,\n  profile_visits       bigint,\n  raw                  jsonb,\n  primary key (connected_account_id, day)\n);\n\n-- ---------------------------------------------------------------------------\n-- Reports and the learning loop (stage 5)\n-- ---------------------------------------------------------------------------\n\ncreate table reports (\n  id                text primary key,                    -- rpt_...\n  workspace_id      text not null references workspaces(id) on delete cascade,\n  kind              text not null check (kind in ('weekly', 'autopsy')),\n  published_post_id text references published_posts(id) on delete cascade,\n  period_start      timestamptz,\n  period_end        timestamptz,\n  input_table       jsonb not null,                      -- the numbers, computed in code\n  body              jsonb not null,                      -- Claude's interpretation, with post citations\n  created_at        timestamptz not null default now()\n);\ncreate unique index reports_autopsy_once on reports (published_post_id) where kind = 'autopsy';\n\n-- \"What next\" items, as structured rules the ideation engine reads directly.\ncreate table guidance_rules (\n  id               text primary key,                     -- rul_...\n  workspace_id     text not null references workspaces(id) on delete cascade,\n  platform         text,\n  feature          text not null,\n  value            text not null,\n  action           text not null check (action in ('prefer', 'avoid', 'test')),\n  share            numeric,                              -- e.g. 2 of 3 reels -> 0.67\n  rationale        text not null,\n  source_report_id text references reports(id) on delete set null,\n  active_from      timestamptz not null default now(),\n  active_until     timestamptz\n);\n\n-- Priors for the shrinkage estimate (week 1: competitor winners; later: niche averages).\ncreate table feature_priors (\n  workspace_id  text not null references workspaces(id) on delete cascade,\n  platform      text not null,\n  feature       text not null,\n  value         text not null,\n  mu_prior      numeric not null,                        -- prior mean of log(PI)\n  source        text not null,\n  updated_at    timestamptz not null default now(),\n  primary key (workspace_id, platform, feature, value)\n);\n\ncreate table explore_state (\n  workspace_id  text not null references workspaces(id) on delete cascade,\n  platform      text not null,\n  explore_share numeric not null default 0.20,\n  reason        text,\n  updated_at    timestamptz not null default now(),\n  primary key (workspace_id, platform)\n);\n\n-- ---------------------------------------------------------------------------\n-- Operations: cost log, provider cache, job queue\n-- ---------------------------------------------------------------------------\n\ncreate table cost_log (\n  id                 bigserial primary key,\n  workspace_id       text references workspaces(id) on delete set null,\n  task               text not null,\n  model              text not null,\n  input_tokens       integer not null default 0,\n  output_tokens      integer not null default 0,\n  cache_read_tokens  integer not null default 0,\n  cache_write_tokens integer not null default 0,\n  batch              boolean not null default false,\n  cost_usd           numeric(12, 6) not null,\n  latency_ms         integer,\n  created_at         timestamptz not null default now()\n);\ncreate index cost_log_ws_day on cost_log (workspace_id, created_at);\n\n-- \"Never re-fetch\": raw provider responses cached by request key.\ncreate table provider_cache (\n  key         text primary key,\n  provider    text not null,\n  body        jsonb not null,\n  fetched_at  timestamptz not null default now(),\n  expires_at  timestamptz not null\n);\n\n-- Portable job queue (pgmq works too; this keeps local dev and tests dependency-free).\ncreate table jobs (\n  id           bigserial primary key,\n  kind         text not null,\n  payload      jsonb not null default '{}'::jsonb,\n  run_at       timestamptz not null default now(),\n  status       text not null default 'queued' check (status in ('queued', 'running', 'done', 'failed')),\n  attempts     integer not null default 0,\n  max_attempts integer not null default 5,\n  last_error   text,\n  dedupe_key   text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\ncreate index jobs_ready on jobs (run_at) where status = 'queued';\ncreate unique index jobs_dedupe on jobs (dedupe_key) where dedupe_key is not null and status in ('queued', 'running');\n" },
  { name: "0002_analytics_and_learning.sql", sql: "-- Analytics (performance index, baselines, rolling stats) and the learning model.\n-- All numbers are computed here or in code; Claude only interprets them.\n\nset search_path = ideation, public, extensions;\n\n-- Historic posts pulled when an account connects have no 72 h snapshot, only a\n-- lifetime count. They are stored with offset_label = 'backfill'. Lifetime views\n-- are >= 72 h views, so using them in the baseline is conservative (it makes PI\n-- harder, not easier, to beat) and it disappears as real 72 h snapshots arrive.\n\n-- One row per published post with the 72 h metrics the index is built on.\ncreate view v_post_metrics_72h as\nselect\n  p.id                 as post_id,\n  p.workspace_id,\n  p.platform,\n  p.published_at,\n  p.features,\n  p.idea_id,\n  p.brief_id,\n  bb.goal,\n  coalesce(s72.views, sbf.views)                                  as views,\n  case when s72.views is not null then '72h'\n       when sbf.views is not null then 'backfill' end            as views_basis,\n  s72.link_clicks,\n  s72.profile_visits,\n  s72.followers_gained,\n  case when num_nonnulls(s72.likes, s72.comments, s72.shares, s72.saves, s72.sends) > 0\n       then coalesce(s72.likes, 0) + coalesce(s72.comments, 0) + coalesce(s72.shares, 0)\n          + coalesce(s72.saves, 0) + coalesce(s72.sends, 0) end  as engagements,\n  -- The goal metric: link clicks for leads/sales, follows (or profile visits) for reach.\n  case bb.goal\n    when 'leads' then s72.link_clicks\n    when 'sales' then s72.link_clicks\n    when 'reach' then coalesce(s72.followers_gained, s72.profile_visits)\n    when 'engagement' then\n      case when num_nonnulls(s72.likes, s72.comments, s72.shares, s72.saves, s72.sends) > 0\n           then coalesce(s72.likes, 0) + coalesce(s72.comments, 0) + coalesce(s72.shares, 0)\n              + coalesce(s72.saves, 0) + coalesce(s72.sends, 0) end\n  end                                                             as goal_value\nfrom published_posts p\njoin brand_brains bb on bb.workspace_id = p.workspace_id\nleft join metric_snapshots s72 on s72.published_post_id = p.id and s72.offset_label = '72h'\nleft join metric_snapshots sbf on sbf.published_post_id = p.id and sbf.offset_label = 'backfill';\n\n-- PI = views at 72 h / median(views at 72 h, same platform, previous 20 posts).\n-- A baseline needs at least 3 earlier posts; before that PI stays null (cold start).\ncreate view v_post_performance as\nselect\n  m.*,\n  b.baseline_views,\n  b.baseline_n,\n  case when b.baseline_n >= 3 and b.baseline_views > 0 and m.views_basis = '72h'\n       then m.views / b.baseline_views end                        as pi,\n  g.baseline_goal,\n  case when g.baseline_n >= 3 and g.baseline_goal > 0 and m.goal_value is not null\n       then m.goal_value / g.baseline_goal end                    as goal_index\nfrom v_post_metrics_72h m\nleft join lateral (\n  select percentile_cont(0.5) within group (order by prev.views)::numeric as baseline_views,\n         count(*) as baseline_n\n  from (\n    select q.views from v_post_metrics_72h q\n    where q.workspace_id = m.workspace_id and q.platform = m.platform\n      and q.published_at < m.published_at and q.views is not null\n    order by q.published_at desc limit 20\n  ) prev\n) b on true\nleft join lateral (\n  select percentile_cont(0.5) within group (order by prev.goal_value)::numeric as baseline_goal,\n         count(*) as baseline_n\n  from (\n    select q.goal_value from v_post_metrics_72h q\n    where q.workspace_id = m.workspace_id and q.platform = m.platform\n      and q.published_at < m.published_at and q.goal_value is not null\n    order by q.published_at desc limit 20\n  ) prev\n) g on true;\n\n-- Pre-aggregated copy for sub-second page loads; refreshed after each ingestion pass.\ncreate materialized view mv_post_performance as select * from v_post_performance;\ncreate unique index mv_post_performance_pk on mv_post_performance (post_id);\ncreate index mv_post_performance_ws on mv_post_performance (workspace_id, platform, published_at desc);\n\n-- Rolling 10-post median, 25th percentile and hit rate as of each post.\ncreate view v_rolling_by_post as\nselect\n  p.post_id, p.workspace_id, p.platform, p.published_at,\n  r.median_views, r.p25_views, r.hit_rate, r.n\nfrom mv_post_performance p\ncross join lateral (\n  select percentile_cont(0.5)  within group (order by x.views)::numeric as median_views,\n         percentile_cont(0.25) within group (order by x.views)::numeric as p25_views,\n         avg(case when x.pi > 1 then 1.0 when x.pi is not null then 0.0 end) as hit_rate,\n         count(*) as n\n  from (\n    select q.views, q.pi from mv_post_performance q\n    where q.workspace_id = p.workspace_id and q.platform = p.platform\n      and q.published_at <= p.published_at and q.views is not null\n    order by q.published_at desc limit 10\n  ) x\n) r\nwhere p.views is not null;\n\n-- The overview chart: the rolling values as they stood at the end of each week.\ncreate view v_rolling_weekly as\nselect distinct on (workspace_id, platform, week)\n  workspace_id, platform, date_trunc('week', published_at) as week,\n  median_views, p25_views, hit_rate, n\nfrom (select *, date_trunc('week', published_at) as week from v_rolling_by_post) t\norder by workspace_id, platform, week, published_at desc;\n\n-- ---------------------------------------------------------------------------\n-- Learning model: shrunk estimate of log(PI) per brand x platform x feature value\n--   mu_hat = (n * mean + k * mu_prior) / (n + k),  k = 5\n-- The posterior standard error uses the brand's pooled variance of log(PI)\n-- (default 0.49, i.e. sd 0.7, until there are 5 posts). Probability of beating\n-- the baseline, P(log PI > 0) = Phi(mu / se), is computed in code, where an\n-- idea's mu = intercept + sum of (mu_hat - intercept) over its feature values.\n-- ---------------------------------------------------------------------------\n\ncreate view v_feature_stats as\nselect\n  m.workspace_id, m.platform, f.key as feature, f.value #>> '{}' as value,\n  count(*)                 as n,\n  avg(ln(m.pi))::numeric   as mean_log_pi\nfrom v_post_performance m\ncross join lateral jsonb_each(m.features) f\nwhere m.pi > 0 and jsonb_typeof(f.value) in ('string', 'number', 'boolean')\ngroup by 1, 2, 3, 4;\n\ncreate view v_pooled_variance as\nselect workspace_id, platform,\n       count(*) as n_posts,\n       avg(ln(pi))::numeric as mean_log_pi,   -- the intercept: the brand's typical log(PI)\n       case when count(*) >= 5 then greatest(var_samp(ln(pi)), 0.05) else 0.49 end::numeric as sigma2\nfrom v_post_performance\nwhere pi > 0\ngroup by 1, 2;\n\ncreate view v_feature_estimates as\nwith k as (select 5::numeric as k)\nselect\n  coalesce(s.workspace_id, pr.workspace_id) as workspace_id,\n  coalesce(s.platform, pr.platform)         as platform,\n  coalesce(s.feature, pr.feature)           as feature,\n  coalesce(s.value, pr.value)               as value,\n  coalesce(s.n, 0)                          as n,\n  s.mean_log_pi,\n  coalesce(pr.mu_prior, 0)                  as mu_prior,\n  (coalesce(s.n, 0) * coalesce(s.mean_log_pi, 0) + k.k * coalesce(pr.mu_prior, 0))\n    / (coalesce(s.n, 0) + k.k)              as mu_hat,\n  sqrt(coalesce(v.sigma2, 0.49) / (coalesce(s.n, 0) + k.k)) as se\nfrom v_feature_stats s\nfull outer join feature_priors pr\n  on pr.workspace_id = s.workspace_id and pr.platform = s.platform\n and pr.feature = s.feature and pr.value = s.value\ncross join k\nleft join v_pooled_variance v\n  on v.workspace_id = coalesce(s.workspace_id, pr.workspace_id)\n and v.platform = coalesce(s.platform, pr.platform);\n\n-- Count of posts with results per platform, used for the cold-start switch (L -> P).\ncreate view v_platform_post_counts as\nselect workspace_id, platform, count(*) filter (where pi is not null) as posts_with_pi\nfrom v_post_performance\ngroup by 1, 2;\n" },
  { name: "0003_brand_research.sql", sql: "-- Brand research: what the company sells (and which lines earn the money),\n-- its public profiles, and researched competitor suggestions.\nset search_path = ideation, public, extensions;\n\nalter table brand_brains\n  add column if not exists description text,\n  add column if not exists industry text,\n  add column if not exists country text,\n  add column if not exists social_links jsonb not null default '[]'::jsonb,\n  add column if not exists competitor_suggestions jsonb not null default '[]'::jsonb,\n  add column if not exists research jsonb;\n\n-- Row Level Security on every ideation table. The app connects as the tables'\n-- owner, which RLS does not restrict; this only closes access through\n-- Supabase's public API keys.\ndo $$\ndeclare t record;\nbegin\n  for t in select tablename from pg_tables where schemaname = 'ideation' loop\n    execute format('alter table ideation.%I enable row level security', t.tablename);\n  end loop;\nend $$;\n" },
  { name: "0004_buyer_insight.sql", sql: "-- What buyers ask and what makes them hesitate. Ideas answer these directly.\nset search_path = ideation, public, extensions;\n\nalter table brand_brains\n  add column if not exists buyer_questions text[] not null default '{}',\n  add column if not exists objections text[] not null default '{}';\n" },
  { name: "0005_knowledge.sql", sql: "-- Week 2: business knowledge (every owned site, stored once), uploads, products,\n-- growth plan, campaigns, and brief optimisation caches.\nset search_path = ideation, public, extensions;\n\ncreate extension if not exists pg_trgm with schema extensions;\n\n-- Sites the business owns. Related domains are added automatically when they\n-- are clearly the same brand, otherwise they wait for the user to confirm.\ncreate table if not exists sources (\n  id               text primary key,                        -- src_...\n  workspace_id     text not null references workspaces(id) on delete cascade,\n  domain           text not null,\n  url              text not null,\n  role             text not null default 'primary' check (role in ('primary', 'product_site', 'shop', 'sister_brand', 'link_in_bio', 'other')),\n  added_by         text not null default 'user' check (added_by in ('user', 'auto', 'confirmed')),\n  status           text not null default 'active' check (status in ('active', 'pending_confirm', 'rejected')),\n  relation_score   integer,\n  relation_reasons text[] not null default '{}',\n  boilerplate      text[] not null default '{}',            -- menu/footer lines stripped before any AI\n  last_scanned_at  timestamptz,\n  created_at       timestamptz not null default now(),\n  unique (workspace_id, domain)\n);\n\ncreate table if not exists scan_runs (\n  id              text primary key,                         -- scn_...\n  workspace_id    text not null references workspaces(id) on delete cascade,\n  status          text not null default 'preview' check (status in ('preview', 'extracting', 'done', 'failed', 'cancelled')),\n  counts          jsonb not null default '{}'::jsonb,       -- pages by type, reused, unreadable...\n  est_tokens      integer not null default 0,\n  est_cost_usd    numeric(10, 4) not null default 0,\n  actual_cost_usd numeric(10, 4),\n  batch_id        text,\n  page_ids        text[] not null default '{}',\n  batch_groups    jsonb not null default '{}'::jsonb,       -- custom_id -> page ids\n  pages_total     integer not null default 0,\n  pages_done      integer not null default 0,\n  cards_added     integer not null default 0,\n  error           text,\n  checked_at      timestamptz,\n  started_at      timestamptz,\n  finished_at     timestamptz,\n  created_at      timestamptz not null default now()\n);\ncreate index if not exists scan_runs_ws on scan_runs (workspace_id, created_at desc);\n\n-- One row per page ever fetched. Re-checks are conditional; AI extraction only\n-- runs when the cleaned text changed (content_hash <> extracted_hash).\ncreate table if not exists page_snapshots (\n  id               text primary key,                        -- pag_...\n  workspace_id     text not null references workspaces(id) on delete cascade,\n  source_id        text references sources(id) on delete cascade,\n  url              text not null,\n  page_type        text not null,\n  priority         integer not null default 0,              -- 3 high, 2 medium, 1 low, 0 skip\n  status           text not null default 'fetched' check (status in ('queued', 'fetched', 'unreadable', 'blocked', 'failed', 'skipped')),\n  selected         boolean not null default true,\n  title            text,\n  etag             text,\n  last_modified    text,\n  sitemap_lastmod  timestamptz,\n  content_hash     text,\n  text             text,\n  tokens_est       integer not null default 0,\n  structured       jsonb,                                   -- JSON-LD facts (read without AI)\n  fetched_at       timestamptz,\n  checked_at       timestamptz,\n  extracted_hash   text,\n  extracted_at     timestamptz,\n  prompt_version   text,\n  unique (workspace_id, url)\n);\n\n-- Extraction results keyed by content hash + prompt version, shared across\n-- workspaces: the same page text is never sent to the model twice.\ncreate table if not exists extractions (\n  key         text primary key,\n  result      jsonb not null,\n  created_at  timestamptz not null default now()\n);\n\ncreate table if not exists products (\n  id              text primary key,                         -- prd_...\n  workspace_id    text not null references workspaces(id) on delete cascade,\n  name            text not null,\n  kind            text not null default 'product' check (kind in ('product', 'service')),\n  revenue_role    text check (revenue_role in ('core', 'secondary', 'lead_magnet')),\n  status          text not null default 'active' check (status in ('active', 'launching', 'seasonal', 'retired')),\n  origin          text not null default 'user' check (origin in ('user', 'brand_brain', 'scan', 'upload')),\n  confirmed       boolean not null default true,\n  summary         text,\n  ai_summary      text,\n  summary_hash    text,\n  audience        text,\n  price_text      text,\n  url             text,\n  source_domain   text,\n  benefits        text[] not null default '{}',\n  image_upload_ids text[] not null default '{}',\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\ncreate unique index if not exists products_ws_name on products (workspace_id, lower(name));\n\ncreate table if not exists uploads (\n  id            text primary key,                           -- upl_...\n  workspace_id  text not null references workspaces(id) on delete cascade,\n  sha256        text not null,\n  filename      text not null,\n  mime          text not null,\n  size_bytes    bigint not null default 0,\n  storage_path  text,                                       -- null when storage isn't configured\n  status        text not null default 'pending' check (status in ('pending', 'uploaded', 'processed', 'failed')),\n  pages         integer,\n  cards_added   integer not null default 0,\n  error         text,\n  created_at    timestamptz not null default now(),\n  unique (workspace_id, sha256)\n);\n\ncreate table if not exists knowledge_cards (\n  id            text primary key,                           -- kc_...\n  workspace_id  text not null references workspaces(id) on delete cascade,\n  type          text not null check (type in ('product', 'service', 'feature', 'pricing', 'proof', 'case_study', 'testimonial',\n                  'client', 'faq', 'objection', 'claim', 'disclaimer', 'audience', 'differentiator', 'process', 'event', 'news',\n                  'location', 'person', 'note')),\n  title         text not null,\n  body          text not null default '',\n  attributes    jsonb not null default '{}'::jsonb,\n  product_ids   text[] not null default '{}',\n  sources       jsonb not null default '[]'::jsonb,         -- [{kind, ref, url, quote}]\n  status        text not null default 'suggested' check (status in ('suggested', 'approved', 'rejected', 'stale')),\n  confidence    text not null default 'medium' check (confidence in ('high', 'medium', 'low')),\n  created_by    text not null default 'ai' check (created_by in ('ai', 'user')),\n  embedding     vector(384),\n  used_count    integer not null default 0,\n  first_seen    timestamptz not null default now(),\n  last_verified timestamptz not null default now(),\n  updated_at    timestamptz not null default now()\n);\ncreate index if not exists knowledge_cards_ws on knowledge_cards (workspace_id, status, type);\ncreate index if not exists knowledge_cards_trgm on knowledge_cards using gin ((title || ' ' || body) gin_trgm_ops);\n\ncreate table if not exists objectives (\n  id              text primary key,                         -- obj_...\n  workspace_id    text not null references workspaces(id) on delete cascade,\n  title           text not null,\n  period_start    date,\n  period_end      date,\n  segment         text,\n  product_ids     text[] not null default '{}',\n  motion          text[] not null default '{}',\n  stage_messages  jsonb not null default '{}'::jsonb,\n  success_metric  text,\n  target_value    numeric,\n  current_value   numeric,\n  weight          numeric not null default 1,\n  status          text not null default 'active' check (status in ('active', 'done', 'paused')),\n  created_at      timestamptz not null default now()\n);\n\ncreate table if not exists campaigns (\n  id                 text primary key,                      -- cmp_... is taken by competitors; campaigns use cpg_\n  workspace_id       text not null references workspaces(id) on delete cascade,\n  objective_id       text references objectives(id) on delete set null,\n  name               text not null,\n  goal               text not null default 'leads' check (goal in ('awareness', 'leads', 'sales', 'launch', 'event', 'retention')),\n  product_ids        text[] not null default '{}',\n  audience           text,\n  key_message        text,\n  offer              text,\n  cta_text           text,\n  cta_url            text,\n  start_date         date,\n  end_date           date,\n  platforms          text[] not null default '{}',\n  posts_per_week     integer not null default 3,\n  phases             jsonb not null default '[]'::jsonb,\n  success_metric     text,\n  target_value       numeric,\n  current_value      numeric,\n  knowledge_card_ids text[] not null default '{}',\n  status             text not null default 'draft' check (status in ('draft', 'active', 'done')),\n  created_at         timestamptz not null default now()\n);\n\n-- Ideas carry the chain objective -> campaign -> product -> buyer stage.\nalter table ideas\n  add column if not exists campaign_id text references campaigns(id) on delete set null,\n  add column if not exists objective_id text references objectives(id) on delete set null,\n  add column if not exists product_id text references products(id) on delete set null,\n  add column if not exists campaign_phase text,\n  add column if not exists planned_for date,\n  add column if not exists grounded boolean not null default false;\nalter table ideas drop constraint if exists ideas_mode_check;\nalter table ideas add constraint ideas_mode_check check (mode in ('autopilot', 'give_me_ideas', 'refine', 'campaign'));\ncreate index if not exists ideas_campaign on ideas (campaign_id) where campaign_id is not null;\n\n-- Free YouTube keyword checks (search.list costs 100 of 10,000 daily units): cached 7 days.\ncreate table if not exists youtube_keyword_cache (\n  keyword     text not null,\n  region      text not null default '',\n  results     jsonb not null,\n  fetched_at  timestamptz not null default now(),\n  primary key (keyword, region)\n);\n\n-- Nightly ideation skips idle workspaces (see precompute): track the last visit.\nalter table workspaces add column if not exists last_seen_at timestamptz;\n\n-- Existing Brand Brain offers become product records.\ninsert into products (id, workspace_id, name, revenue_role, price_text, url, summary, origin, confirmed)\nselect 'prd_' || substr(md5(b.workspace_id || lower(o->>'name')), 1, 24), b.workspace_id, o->>'name',\n       case when o->>'revenue_role' in ('core', 'secondary', 'lead_magnet') then o->>'revenue_role' end,\n       o->>'price', o->>'url', o->>'description', 'brand_brain', true\nfrom brand_brains b, jsonb_array_elements(b.offers) o\nwhere coalesce(o->>'name', '') <> ''\non conflict do nothing;\n\ndo $$\ndeclare t record;\nbegin\n  for t in select tablename from pg_tables where schemaname = 'ideation' loop\n    execute format('alter table ideation.%I enable row level security', t.tablename);\n  end loop;\nend $$;\n" },
];
